import { $actions } from "../../DisplayObjectUtil";
/**
 * @description フレームアクションがなくなるまで実行
 *              Execute until there are no frame actions
 *
 * @return {void}
 * @method
 * @protected
 */
export const execute = () => {
    while ($actions.length) {
        const movieClip = $actions.pop();
        const actionMap = movieClip.$actions;
        if (!actionMap) {
            continue;
        }
        const frame = movieClip.currentFrame;
        if (!actionMap.has(frame)) {
            continue;
        }
        const actions = actionMap.get(frame);
        if (!actions) {
            continue;
        }
        for (let idx = 0; idx < actions.length; idx++) {
            try {
                actions[idx].apply(movieClip);
            }
            catch (error) {
                console.error(error);
            }
        }
    }
};
